// Brand logo images, embedded as data URIs so no extra file upload is needed.
// Generated from user-provided logo images.
export const BRAND_LOGOS: Record<string, string> = {
  xiaomi: 'data:image/png;base64,',
  tecno: 'data:image/png;base64,',
  oppo: 'data:image/png;base64,',
  infinix: 'data:image/png;base64,',
  huawei: 'data:image/png;base64,',
  redmi: 'data:image/png;base64,',
  samsung: 'data:image/png;base64,',
  asus: 'data:image/png;base64,',
  hp: 'data:image/png;base64,',
  lenovo: 'data:image/png;base64,',
  apple: 'data:image/png;base64,',
  dell: 'data:image/png;base64,',
  toyota: 'data:image/png;base64,',
  nissan: 'data:image/png;base64,',
  hyundai: 'data:image/png;base64,',
  suzuki: 'data:image/png;base64,',
  volkswagen: 'data:image/png;base64,',
  tvs: 'data:image/png;base64,',
  bajaj: 'data:image/png;base64,',
};

// Some listed brand names differ from the logo file name (e.g. the
// phone brand 'iPhone' uses Apple's logo).
export const BRAND_LOGO_ALIASES: Record<string, string> = {
  iphone: 'apple',
};

export function getBrandLogo(brand: string): string | null {
  const key = BRAND_LOGO_ALIASES[brand.toLowerCase()] || brand.toLowerCase();
  return BRAND_LOGOS[key] || null;
}